def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                y,x=stack.pop(); pts.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append((pts,color,min(x for y,x in pts),max(x for y,x in pts)))
    if not objs:return [row[:] for row in grid]
    objs.sort(key=lambda o:o[2])
    start=min(o[2] for o in objs)
    objs.sort(key=lambda o:len(o[0]))
    out=[[0]*w for _ in range(h)]
    for pts,col,left,right in objs:
        for y,x in pts:
            xx=x-left+start
            if 0<=xx<w:out[y][xx]=col
        start+=right-left+2
    return out

